(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const cardOf = (text) => [...document.querySelectorAll('.pj-card')].find((c) => (c.innerText || '').includes(text));
  const out = {};
  const cards = [...document.querySelectorAll('.tb-project-main')];
  const target = cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0];
  out.openedWork = (target.innerText || '').split('\n')[0];
  target.click();
  await sleep(3000);
  out.before = (cardOf('项目信息')?.innerText || '').replace(/\s+/g, ' ').match(/使用元器件 [0-9]+ 种/)?.[0] || null;

  const card = cardOf('项目描述');
  card.querySelector('.pj-link-btn').click();
  await sleep(400);
  const tas = card.querySelectorAll('textarea');
  setV(tas[0], '持久化标记：这台循迹小车会自己找黑线。');
  [...card.querySelectorAll('.pj-btn-primary')].find((b) => b.textContent.trim() === '保存').click();
  await sleep(1200);
  out.savedDesc = (cardOf('项目描述')?.innerText || '').replace(/\s+/g, ' ').slice(0, 60);

  const bom = cardOf('元器件清单');
  [...bom.querySelectorAll('.pj-link-btn')].find((b) => b.textContent.includes('添加元件')).click();
  await sleep(400);
  const inputs = cardOf('元器件清单').querySelectorAll('input');
  setV(inputs[0], '持久化测试元件');
  setV(inputs[1], '电阻');
  setV(inputs[2], '10k');
  setV(inputs[3], '2');
  [...cardOf('元器件清单').querySelectorAll('.pj-btn-primary')].find((b) => b.textContent.trim() === '加入作品').click();
  await sleep(1800);
  out.after = (cardOf('项目信息')?.innerText || '').replace(/\s+/g, ' ').match(/使用元器件 [0-9]+ 种/)?.[0] || null;
  out.toast = document.querySelector('.pj-toast')?.textContent || null;
  return JSON.stringify(out);
})()
